document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.directory-card[data-group]').forEach(x=>{x.hidden=b.dataset.filter!=='全部'&&x.dataset.group!==b.dataset.filter;if(!x.hidden)n++;});const s=document.getElementById('filter-status');if(s)s.textContent='显示 '+n+' 个指数';}));document.querySelectorAll('[data-chart-switch]').forEach(b=>b.addEventListener('click',()=>{const box=b.closest('[data-chart-box]');box.querySelectorAll('[data-chart-switch]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const img=box.querySelector('img.research-chart');img.src=b.dataset.chartSwitch;img.alt=b.dataset.label;box.querySelector('.chart-link').href=b.dataset.chartSwitch;}));document.querySelectorAll('[data-toggle-layer]').forEach(b=>b.addEventListener('click',()=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));document.querySelectorAll(b.dataset.toggleLayer).forEach(x=>x.style.display=on?'':'none');}));